    "Questions": "Questions",
    "Everything you need to know about the platform, security, and billing.": "Everything you need to know about the platform, security, and billing.",
    "How easy is it to configure biometric attendance?": "How easy is it to configure biometric attendance?",
    "It is highly straightforward. Once you register employee face profiles in the system, our smart edge recognition technology automatically syncs check-in/out logs directly with your dashboard.": "It is highly straightforward. Once you register employee face profiles in the system, our smart edge recognition technology automatically syncs check-in/out logs directly with your dashboard.",
    "Do I need technical skills to set up payroll?": "Do I need technical skills to set up payroll?",
    "Not at all. Our system is designed with a user-friendly interface. You can set up payroll rules, tax deductions, and bonuses in a few clicks. Our support team is also available to help you with the initial configuration.": "Not at all. Our system is designed with a user-friendly interface. You can set up payroll rules, tax deductions, and bonuses in a few clicks. Our support team is also available to help you with the initial configuration.",
    "Is my company data secure?": "Is my company data secure?",
    "Yes, we take security very seriously. All data is encrypted both in transit and at rest using bank-grade AES-256 encryption. We also provide role-based access control and detailed activity logs.": "Yes, we take security very seriously. All data is encrypted both in transit and at rest using bank-grade AES-256 encryption. We also provide role-based access control and detailed activity logs.",
    "Does the system support mobile devices?": "Does the system support mobile devices?",
    "Absolutely. Employees can use our responsive mobile web app to mark attendance (via GPS or QR code), apply for leaves, and view their payslips on the go.": "Absolutely. Employees can use our responsive mobile web app to mark attendance (via GPS or QR code), apply for leaves, and view their payslips on the go.",
    "Can I upgrade or downgrade my plan later?": "Can I upgrade or downgrade my plan later?",
    "Yes, you can change your subscription plan at any time from your billing dashboard. Changes will be pro-rated and reflected in your next billing cycle.": "Yes, you can change your subscription plan at any time from your billing dashboard. Changes will be pro-rated and reflected in your next billing cycle.",
    "How does the 7-day Free Trial work?": "How does the 7-day Free Trial work?",
    "You receive instant access to all enterprise HRM modules for 7 days with zero upfront payment or credit card required. You can upgrade to a paid plan anytime without losing any configured data.": "You receive instant access to all enterprise HRM modules for 7 days with zero upfront payment or credit card required. You can upgrade to a paid plan anytime without losing any configured data.",
