    "Frequently Asked": "अक्सर पूछे जाने वाले",
    "Questions": "प्रश्न",
    "Everything you need to know about the platform, security, and billing.": "प्लेटफ़ॉर्म, सुरक्षा और बिलिंग के बारे में आपको जो कुछ जानने की आवश्यकता है।",
    "How easy is it to configure biometric attendance?": "बायोमेट्रिक उपस्थिति को कॉन्फ़िगर करना कितना आसान है?",
    "It is highly straightforward. Once you register employee face profiles in the system, our smart edge recognition technology automatically syncs check-in/out logs directly with your dashboard.": "यह बेहद सरल है। जब आप सिस्टम में कर्मचारियों के चेहरे की प्रोफाइल पंजीकृत करते हैं, तो हमारी स्मार्ट पहचान तकनीक चेक-इन/आउट लॉग को स्वचालित रूप से डैशबोर्ड से सिंक करती है।",
    "Do I need technical skills to set up payroll?": "क्या मुझे पेरोल सेट करने के लिए तकनीकी कौशल की आवश्यकता है?",
    "Not at all. Our system is designed with a user-friendly interface. You can set up payroll rules, tax deductions, and bonuses in a few clicks. Our support team is also available to help you with the initial configuration.": "बिल्कुल नहीं। हमारा सिस्टम उपयोगकर्ता-अनुकूल इंटरफ़ेस के साथ डिज़ाइन किया गया है। आप कुछ ही क्लिक में पेरोल नियम, कर कटौती और बोनस सेट कर सकते हैं।",
    "Is my company data secure?": "क्या मेरी कंपनी का डेटा सुरक्षित है?",
    "Yes, we take security very seriously. All data is encrypted both in transit and at rest using bank-grade AES-256 encryption. We also provide role-based access control and detailed activity logs.": "हाँ, हम सुरक्षा को अत्यंत गंभीरता से लेते हैं। बैंक-ग्रेड AES-256 एन्क्रिप्शन का उपयोग करके सभी डेटा सुरक्षित रूप से एन्क्रिप्ट किया गया है।",
    "Does the system support mobile devices?": "क्या सिस्टम मोबाइल उपकरणों का समर्थन करता है?",
    "Absolutely. Employees can use our responsive mobile web app to mark attendance (via GPS or QR code), apply for leaves, and view their payslips on the go.": "हाँ बिल्कुल। कर्मचारी मोबाइल वेब ऐप का उपयोग करके उपस्थिति दर्ज कर सकते हैं, छुट्टियों के लिए आवेदन कर सकते हैं और अपनी पेस्लिप देख सकते हैं।",
    "Can I upgrade or downgrade my plan later?": "क्या मैं बाद में अपने प्लान को अपग्रेड या डाउनग्रेड कर सकता हूँ?",
    "Yes, you can change your subscription plan at any time from your billing dashboard. Changes will be pro-rated and reflected in your next billing cycle.": "हाँ, आप अपने बिलिंग डैशबोर्ड से किसी भी समय अपनी सदस्यता योजना बदल सकते हैं।",
    "How does the 7-day Free Trial work?": "7-दिवसीय नि:शुल्क परीक्षण कैसे काम करता है?",
    "You receive instant access to all enterprise HRM modules for 7 days with zero upfront payment or credit card required. You can upgrade to a paid plan anytime without losing any configured data.": "आपको बिना किसी अग्रिम भुगतान या क्रेडिट कार्ड के 7 दिनों के लिए सभी उद्यम एचआरएम मॉड्यूल तक त्वरित पहुंच प्राप्त होती है।",
