    "Navigate to the Settings menu from the sidebar.": "साइडबार से सेटिंग्स मेनू पर जाएं।",
    "Enter your company details — Shift Timing, Grace Period, and Late Deduction rules.": "कंपनी विवरण दर्ज करें — शिफ्ट समय, छूट अवधि और देर से कटौती के नियम।",
