    "Set their salary rate (Hourly or Monthly) and department.": "वेतन दर (प्रति घंटा या मासिक) और विभाग निर्धारित करें।",
    "For Face Attendance, go to Face Register and scan each employee's face.": "चेहरा उपस्थिति के लिए, चेहरा पंजीकरण पर जाएं और कर्मचारियों का चेहरा स्कैन करें।",
    "Set Up Kiosk Terminal": "कियोस्क टर्मिनल सेट करें",
    "To take attendance on a tablet or secondary device, go to Kiosk Settings.": "टैबलेट या डिवाइस पर उपस्थिति लेने के लिए कियोस्क सेटिंग्स पर जाएं।",
    "Click \"Launch Kiosk Terminal\" to open the attendance kiosk.": "उपस्थिति कियोस्क खोलने के लिए \"लॉन्च कियोस्क टर्मिनल\" पर क्लिक करें।",
    "Employees can now punch in using their ID or Face Scan on the terminal.": "कर्मचारी अब टर्मिनल पर अपनी आईडी या फेस स्कैन से पंच कर सकते हैं।",
    "Manage Leaves & Holidays": "छुट्टियां और सार्वजनिक अवकाश प्रबंधित करें",
    "Go to Attendance > Holidays and add your upcoming public holidays in advance.": "उपस्थिति > अवकाश पर जाएं और आगामी सार्वजनिक छुट्टियां जोड़ें।",
    "Employees can apply for leave directly from their own panel.": "कर्मचारी सीधे अपने पैनल से छुट्टी के लिए आवेदन कर सकते हैं।",
    "Review and Approve or Reject leave requests from the Leaves section.": "छुट्टियां अनुभाग से छुट्टी अनुरोधों की समीक्षा करें और स्वीकृत या अस्वीकृत करें।",
    "Review Expense Claims": "खर्च के दावों की समीक्षा करें",
    "When employees incur business expenses (Travel, Food, etc.), they submit a claim.": "जब कर्मचारी व्यावसायिक खर्च (यात्रा, भोजन आदि) करते हैं, तो वे दावा दर्ज करते हैं।",
    "Go to the Claims tab, verify the receipt, and Approve it.": "दावे (Claims) टैब पर जाएं, रसीद सत्यापित करें और इसे स्वीकृत करें।",
    "Once approved, the reimbursement amount is automatically added to their monthly salary.": "स्वीकृत होने के बाद, प्रतिपूर्ति राशि स्वचालित रूप से उनके मासिक वेतन में जुड़ जाती है।",
    "Generate Payroll": "पेरोल और वेतन पर्ची बनाएं",
    "At the end of the month, go to the Payroll tab.": "महीने के अंत में, पेरोल टैब पर जाएं।",
    "Click \"Process Cycle\". The system will automatically calculate Late Deductions, Leaves, Claims, and configured Employee & Employer Contributions.": "\"प्रोसेस साइकिल\" पर क्लिक करें। सिस्टम स्वचालित रूप से देर से कटौतियों, छुट्टियों, दावों और अंशदानों की गणना करेगा।",
    "Once everything looks correct, confirm and your Pay Slips will be generated!": "एक बार सब कुछ सही दिखने के बाद, पुष्टि करें और आपकी वेतन पर्ची बन जाएगी!",
