    "GOT QUESTIONS?": "¿TIENE PREGUNTAS?",
    "Frequently Asked": "Preguntas",
    "Questions": "Frecuentes",
    "Everything you need to know about the platform, security, and billing.": "Todo lo que necesita saber sobre la plataforma, seguridad y facturación.",
    "How easy is it to configure biometric attendance?": "¿Qué tan fácil es configurar la asistencia biométrica?",
    "It is highly straightforward. Once you register employee face profiles in the system, our smart edge recognition technology automatically syncs check-in/out logs directly with your dashboard.": "Es muy sencillo. Una vez registrados los perfiles faciales, el sistema sincroniza automáticamente los fichajes con su panel.",
    "Do I need technical skills to set up payroll?": "¿Necesito conocimientos técnicos para configurar la nómina?",
    "Not at all. Our system is designed with a user-friendly interface. You can set up payroll rules, tax deductions, and bonuses in a few clicks. Our support team is also available to help you with the initial configuration.": "Para nada. Puede configurar reglas de nómina, deducciones y bonificaciones en pocos clics de manera intuitiva.",
    "Is my company data secure?": "¿Están seguros los datos de mi empresa?",
    "Yes, we take security very seriously. All data is encrypted both in transit and at rest using bank-grade AES-256 encryption. We also provide role-based access control and detailed activity logs.": "Sí, todos los datos están cifrados con encriptación AES-256 de nivel bancario y control de acceso basado en roles.",
    "Does the system support mobile devices?": "¿El sistema es compatible con dispositivos móviles?",
    "Absolutely. Employees can use our responsive mobile web app to mark attendance (via GPS or QR code), apply for leaves, and view their payslips on the go.": "Por supuesto. Los empleados pueden fichar por GPS o código QR, solicitar permisos y ver sus nóminas desde el móvil.",
    "Can I upgrade or downgrade my plan later?": "¿Puedo cambiar de plan más adelante?",
    "Yes, you can change your subscription plan at any time from your billing dashboard. Changes will be pro-rated and reflected in your next billing cycle.": "Sí, puede cambiar su plan en cualquier momento desde el panel de facturación de forma prorrateada.",
    "How does the 7-day Free Trial work?": "¿Cómo funciona la prueba gratuita de 7 días?",
    "You receive instant access to all enterprise HRM modules for 7 days with zero upfront payment or credit card required. You can upgrade to a paid plan anytime without losing any configured data.": "Obtiene acceso completo a todos los módulos durante 7 días sin tarjeta de crédito ni compromiso.",
