    "Frequently Asked": "Häufig gestellte",
    "Questions": "Fragen",
    "Everything you need to know about the platform, security, and billing.": "Alles, was Sie über Plattform, Sicherheit und Abrechnung wissen müssen.",
    "How easy is it to configure biometric attendance?": "Wie einfach lässt sich die biometrische Zeiterfassung einrichten?",
    "It is highly straightforward. Once you register employee face profiles in the system, our smart edge recognition technology automatically syncs check-in/out logs directly with your dashboard.": "Sehr einfach. Nach der Erfassung der Gesichtsprofile synchronisiert unsere Erkennungstechnologie alle Ein-/Ausstempelungen automatisch mit Ihrem Dashboard.",
    "Do I need technical skills to set up payroll?": "Benötige ich technische Kenntnisse zur Einrichtung der Gehaltsabrechnung?",
    "Not at all. Our system is designed with a user-friendly interface. You can set up payroll rules, tax deductions, and bonuses in a few clicks. Our support team is also available to help you with the initial configuration.": "Überhaupt nicht. Sie können Lohnregeln, Abzüge und Boni mit wenigen Klicks über die benutzerfreundliche Oberfläche einrichten.",
    "Is my company data secure?": "Sind meine Unternehmensdaten sicher?",
    "Yes, we take security very seriously. All data is encrypted both in transit and at rest using bank-grade AES-256 encryption. We also provide role-based access control and detailed activity logs.": "Ja, alle Daten werden sowohl bei der Übertragung als auch im Ruhezustand mit bankenüblicher AES-256-Verschlüsselung geschützt.",
    "Does the system support mobile devices?": "Unterstützt das System mobile Endgeräte?",
    "Absolutely. Employees can use our responsive mobile web app to mark attendance (via GPS or QR code), apply for leaves, and view their payslips on the go.": "Absolut. Mitarbeiter können die mobile Web-App nutzen, um per GPS einzustempeln, Urlaub zu beantragen und Abrechnungen einzusehen.",
    "Can I upgrade or downgrade my plan later?": "Kann ich meinen Tarif später hoch- oder herabstufen?",
    "Yes, you can change your subscription plan at any time from your billing dashboard. Changes will be pro-rated and reflected in your next billing cycle.": "Ja, Sie können Ihren Tarif jederzeit im Abrechnungsbereich anpassen.",
    "How does the 7-day Free Trial work?": "Wie funktioniert die 7-tägige kostenlose Testversion?",
    "You receive instant access to all enterprise HRM modules for 7 days with zero upfront payment or credit card required. You can upgrade to a paid plan anytime without losing any configured data.": "Sie erhalten 7 Tage lang vollen Zugriff auf alle Module – ohne Kreditkarte oder Vorauszahlung.",
