    "Everything you need to know about the platform, security, and billing.": "كل ما تحتاج لمعرفته حول المنصة، الأمان، وخيارات الدفع.",
    "How easy is it to configure biometric attendance?": "ما مدى سهولة ضبط وتفعيل الحضور البيومتري؟",
    "It is highly straightforward. Once you register employee face profiles in the system, our smart edge recognition technology automatically syncs check-in/out logs directly with your dashboard.": "الأمر في غاية السهولة، بمجرد تسجيل بصمة وجه الموظف، يتعرف النظام عليه فورياً وتتم مزامنة الحضور مع لوحة التحكم.",
    "Do I need technical skills to set up payroll?": "هل أحتاج إلى خبرة تقنية لإعداد مسيرات الरोاتب؟",
    "Not at all. Our system is designed with a user-friendly interface. You can set up payroll rules, tax deductions, and bonuses in a few clicks. Our support team is also available to help you with the initial configuration.": "إطلاقاً، تم تصميم النظام ليكون بديهياً وسهلاً للغاية حيث يمكنك ضبط القواعد والاستقطاعات والبدلات بضغطات بسيطة.",
    "Is my company data secure?": "هل بيانات شركتي وموظفي في أمان تام؟",
    "Yes, we take security very seriously. All data is encrypted both in transit and at rest using bank-grade AES-256 encryption. We also provide role-based access control and detailed activity logs.": "نعم بالتأكيد، يتم تشفير كافة البيانات باستخدام خوارزميات AES-256 البنكية مع تحكم دقيق في صلاحيات المستخدمين.",
    "Does the system support mobile devices?": "هل يدعم النظام الهواتف والأجهزة الذكية؟",
    "Absolutely. Employees can use our responsive mobile web app to mark attendance (via GPS or QR code), apply for leaves, and view their payslips on the go.": "بالتأكيد، يمكن للموظفين تسجيل الحضور عبر GPS، وطلب الإجازات والاطلاع على قسائم رواتبهم من هواتفهم بسهولة.",
    "Can I upgrade or downgrade my plan later?": "هل يمكنني ترقية أو تغيير باقة الاشتراك لاحقاً؟",
    "Yes, you can change your subscription plan at any time from your billing dashboard. Changes will be pro-rated and reflected in your next billing cycle.": "نعم، يمكنك تغيير باقتك في أي وقت مباشرة من لوحة إدارة الاشتراكات بكل مرونة.",
    "How does the 7-day Free Trial work?": "كيف تعمل فترة التجربة المجانية لمدة 7 أيام؟",
    "You receive instant access to all enterprise HRM modules for 7 days with zero upfront payment or credit card required. You can upgrade to a paid plan anytime without losing any configured data.": "تحصل على وصول كامل لكافة خصائص النظام لمدة 7 أيام مجاناً دون الحاجة لبطاقة ائتمانية ودون فقدان أي بيانات.",
