/**
 * Resolver function to get translation with case-insensitive, punctuation-tolerant fallback matching
 */
export const translate = (key, language = 'en', fallback = null) => {
  if (key === null || key === undefined) return '';
  const strKey = String(key).trim();
  if (!strKey) return '';
  
  const langKey = (language || 'en').toLowerCase();
  
  let targetLang = 'en';
  if (langKey.includes('hi') || langKey.includes('hindi')) targetLang = 'hi';
  else if (langKey.includes('es') || langKey.includes('span') || langKey.includes('español')) targetLang = 'es';
  else if (langKey.includes('de') || langKey.includes('ger') || langKey.includes('deutsch')) targetLang = 'de';
  else if (langKey.includes('ar') || langKey.includes('arab')) targetLang = 'ar';

  const dict = TRANSLATIONS[targetLang] || TRANSLATIONS['en'];
  
  // 1. Direct exact match
  if (dict[strKey]) return dict[strKey];

  // 2. Normalized lookup (case-insensitive & trimmed)
  const keyLower = strKey.toLowerCase();
  const foundEntry = Object.entries(dict).find(([k]) => k.toLowerCase() === keyLower);
  if (foundEntry && foundEntry[1]) return foundEntry[1];

  // 3. Punctuation stripped lookup (e.g. 'Plan:' -> 'Plan', 'Rating:' -> 'Rating')
  const cleanKey = strKey.replace(/[:\.\?\!]+$/, '').trim().toLowerCase();
  const foundClean = Object.entries(dict).find(([k]) => k.toLowerCase().replace(/[:\.\?\!]+$/, '').trim() === cleanKey);
  if (foundClean && foundClean[1]) {
    if (strKey.endsWith(':') && !foundClean[1].endsWith(':')) {
      return foundClean[1] + ':';
    }
    return foundClean[1];
  }

  return fallback || strKey;
};
